<template>
  <q-input
    class="width-500"
    dense
    v-model="params.search"
    autofocus
    @update:model-value="fetchData"
    :debounce="1000"
    :placeholder="$t('search_by_document_id')"
    outlined
    @keyup="onKeyup"
  >
    <template v-slot:append>
      <f-btn icon="tune" appearance="flat">
        <q-menu
          style="width: 400px; min-height: 150px"
          anchor="bottom start"
          self="top left"
          :offset="[353, 10]"
        >
          <div class="q-pa-md">
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('status') }}</span>
              <q-space />
              <CoaStatus />
            </div>
            <div class="float-right q-ml-auto">
              <f-btn
                appearance="secondary"
                class="q-mr-sm mt-20 q-mb-md"
                :label="$t('clear_filters')"
                @click="resetFilters()"
              />
            </div>
          </div>
        </q-menu>
      </f-btn>
    </template>
  </q-input>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { coaDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import CoaStatus from './coa-status.vue';

export default defineComponent({
  components: {
    CoaStatus,
  },
  watch: {
    'params.search': {
      deep: true,
      handler: function (newVal, oldVal) {
        this.handleQuikFilter();
      },
    },
  },
  methods: {
    onKeyup(event: any) {
      if (event.key == 'Enter') {
        this.handleQuikFilter();
        this.fetchData();
      }
    },
    async fetchData() {
      this.resetPagination();
      await this.getCoaData();
    },
    handleQuikFilter() {
      if (!this.params.search || this.params.search.trim() === '') {
        this.quickFilterMap.delete('search');
      } else {
        this.quickFilterMap.set('search', this.params.search);
      }
    },
    resetFilters() {
      this.quickFilterMap.clear();
      this.resetFilter();
      this.fetchData();
    },
  },
  setup() {
    const coa_store = coaDashboardStore();
    const { params, quickFilterMap } = storeToRefs(coa_store);
    const { resetPagination, getCoaData, resetFilter } = coa_store;

    return {
      params,
      quickFilterMap,
      resetPagination,
      getCoaData,
      resetFilter,
    };
  },
});
</script>
