<template>
  <div class="row">
    <span class="q-py-xs q-mt-md q-mr-sm">{{ $t('pagination_size') }}:</span>
    <q-select
      borderless
      dense
      v-model="pagination.page_size"
      :options="pagination_options"
      @update:model-value="getCoaData"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { coaDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  setup() {
    const coa_store = coaDashboardStore();
    const { pagination } = storeToRefs(coa_store);
    const { getCoaData } = coa_store;

    return {
      pagination,
      getCoaData,
      pagination_options: ref(['10', '20', '25', '50']),
    };
  },
  methods: {
    validatePaginationSize() {
      if (this.pagination.page_size <= 50) return;
      this.pagination.page_size = 50;
    },
  },
  mounted() {
    this.validatePaginationSize();
  },
});
</script>
