<template>
  <MessageBanner
    v-if="!user_settings[coa_dashboard_setting]"
    :dissmiss_btn="false"
    :back_route="false"
    :message="$t('ACTION_NOT_ALLOWED')"
  />
  <template v-else>
    <SubHeader name="coa_dashboard" :label="$t('certificate_of_analysis')">
    </SubHeader>

    <div class="dashboard-container dashboard-text-color dashboard-main">
      <CoaDashboardHeader />

      <q-separator class="seperator" />
      <div class="full-width dashboard-list-area q-my-lg">
        <DocBitsTable
          :rows="Object.values(display_data)"
          :columns="tableColumns"
          row-key="id"
          :loading="show_table_loader"
          :features="{ sorting: true, pagination: false, columnReorder: true }"
          table-id="coa_table"
          :no-data-label="$t('no_record_found')"
          dense
          @row-click="({ row }: any) => goToDetails(row)"
        >
          <template #body-cell-status="{ row }">
            <q-badge transparent align="middle" :color="statusColor(row.status)">
              {{ row.status }}
            </q-badge>
          </template>
        </DocBitsTable>

        <div class="back-white flex justify-end">
          <div class="row" style="margin-right: 0">
            <CoaPagination class="q-py-xs q-mr-md" />
            <q-pagination
              v-model="pagination.current_page"
              color="primary"
              :max="pagination.total_pages"
              class="q-py-xs q-mx-md"
              :max-pages="6"
              input
              boundary-links
              @update:model-value="paginationItemClicked()"
            />
          </div>
        </div>
      </div>
    </div>

    <q-inner-loading :showing="loading" style="z-index: 2">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </template>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import dragDropColumn from 'src/mixins/dragDropColumn';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import MessageBanner from 'src/components/MessageBanner.vue';
import generateSavedColumns from 'src/utils/generateSavedColumns';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { coaDashboardStore, useSettingStore } from 'src/store/main';
import { coa_dashboard_setting } from 'src/constants';
import { getStatusColor } from 'src/pages/PurchaseOrders/constants.js';
import ColumnOrderBy from 'src/pages/CertificateOfAnalysis/components/coa-column-orderBy.vue';
import CoaPagination from 'src/pages/CertificateOfAnalysis/components/CoaPagination.vue';
import CoaDashboardHeader from 'src/pages/CertificateOfAnalysis/components/CoaDashboardHeader.vue';
export default defineComponent({
  mixins: [dragDropColumn, generateSavedColumns, dateUtils],
  props: {
    type_name: {
      type: String,
      required: false,
      default: 'coa',
    },
  },
  components: {
    SubHeader,
    ColumnOrderBy,
    DocBitsTable,
    MessageBanner,
    CoaPagination,
    CoaDashboardHeader,
  },
  data() {
    return {
      show_table_loader: ref(false),
      coa_dashboard_setting,
    };
  },
  async mounted() {
    await this.init();
    this.initDragDropColumns('coa_table', 'label');
    document.addEventListener('coa_table-column-drop', this.onDropColumns);
    this.visible_columns = await this.getSavedColumns();
    this.prepareTableColumns();
    document.addEventListener('columnsUpdated', (e: any) => {
      if (e.detail?.visible_columns) {
        this.visible_columns = e.detail.visible_columns;
        this.prepareTableColumns();
      }
    });
  },
  unmounted() {
    document.removeEventListener('columnsUpdated', () => {
      logInfo('removed');
    });
    document.removeEventListener('coa_table-column-drop', this.onDropColumns);
  },
  methods: {
    async init() {
      await this.getCoaList(true);
    },

    prepareTableColumns() {
      if (this.visible_columns && Object.keys(this.visible_columns).length > 0) {
        const cols = Object.values(this.visible_columns)
          .map((col: any) => ({
            name: col.name,
            label: col.translation_key,
            field: col.field,
            actions: col.actions,
            order: col.order,
            required: true,
          }))
          .sort((a: any, b: any) => a.order - b.order);
        this.tableColumns = cols;
      }
    },

    onDropColumns() {
      this.savedOrderColumns(this.tableColumns);
    },
    async savedOrderColumns(columns: any) {
      try {
        this.loading = true;
        await this.saveColumnOrder(columns);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async getCoaList(show_table_loader: boolean) {
      try {
        this.loading = true;
        if (show_table_loader) {
          this.show_table_loader = true;
        }
        await this.getCoaData();
      } catch (err: any) {
        logError(err);
      } finally {
        this.loading = false;
        this.show_table_loader = false;
      }
    },
    async paginationItemClicked() {
      try {
        await this.getCoaList(true);
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },
    setRowStyle(row: any) {
      if (
        row.hasOwnProperty('export_data_fetched') &&
        row['export_data_fetched'] === true
      ) {
        return 'exported-row';
      }
      return '';
    },
    goToDetails(row: any) {
      const id = row?.id as string;
      this.$router.push(`/certificate-of-analysis/${id}`);
    },
    statusColor(status: string) {
      if (status) {
        return getStatusColor(status.toLowerCase()) || 'primary';
      } else {
        return '';
      }
    },
    dateFields(fieldName: string) {
      const dateFieldPatterns = ['created_on', 'updated_on', '_date', '_on'];
      return dateFieldPatterns.some((pattern) => fieldName.includes(pattern));
    },
  },
  setup() {
    const coa_store = coaDashboardStore();
    const { display_data, table_columns, loading, pagination } =
      storeToRefs(coa_store);
    const { getCoaData, getSavedColumns, saveColumnOrder } = coa_store;
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const tableColumns = ref(
      Object.values(table_columns.value)
        .map((column: any) => ({
          name: column.name,
          label: column.translation_key,
          field: column.field,
          actions: column.actions,
          order: column.order,
          required: true,
        }))
        .sort((a, b) => a.order - b.order),
    );

    return {
      table_columns,
      display_data,
      loading,
      pagination,
      tableColumns,
      user_settings,
      visible_columns: ref({}) as dynamicObj,
      getCoaData,
      getSavedColumns,
      saveColumnOrder,
    };
  },
});
</script>

