<template>
  <q-select
    v-model="params.status"
    :options="statusOptions"
    option-label="label"
    option-value="value"
    emit-value
    map-options
    outlined
    dense
    style="width: 200px"
    :label="$t('status')"
    clearable
    @update:model-value="onStatusChange"
  />
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { coaDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  setup() {
    const coa_store = coaDashboardStore();
    const { params, quickFilterMap } = storeToRefs(coa_store);
    const { getCoaData, resetPagination } = coa_store;

    const statusOptions = ref([
      { label: 'Pending', value: 'pending' },
      { label: 'Validated', value: 'validated' },
      { label: 'Ready for Export', value: 'ready_for_export' },
      { label: 'Exported', value: 'exported' },
      { label: 'Error', value: 'error' },
    ]);

    return {
      params,
      quickFilterMap,
      getCoaData,
      resetPagination,
      statusOptions,
    };
  },
  methods: {
    async onStatusChange(value: string | null) {
      if (value) {
        const status = { label: value, value: value };
        this.quickFilterMap.set('status', status);
      } else {
        this.quickFilterMap.delete('status');
      }
      this.resetPagination();
      await this.getCoaData();
    },
  },
});
</script>
