<template>
  <f-btn
    square
    class="q-mr-sm"
    @click="show_column_settings = true"
  >
    <Icon icon="mdi:filter-variant" width="20" height="20" />
    <q-tooltip>{{ $t(label) }}&nbsp;</q-tooltip>
  </f-btn>

  <!-- Dashboard Columns Dialog -->
  <q-dialog
    v-model="show_column_settings"
    @show="beforePopupShow"
    @keydown.esc="show_column_settings = false"
    persistent
    @hide="onDashboardColumnDialogHide"
  >
    <q-card style="width: 900px; max-width: 1060px">
      <q-toolbar class="text-white secondary-toolbar draggable-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('column_settings') }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>
      <q-card-section>
        <!-- Main -->
        <div>
          <div class="row no-wrap justify-around q-pt-md">
            <!-- hidden list -->
            <div class="drop-target rounded-borders q-mr-md">
              <div
                class="box row justify-center items-center"
                style="border-bottom: 1px solid grey"
              >
                {{ $t('hidden_columns') }}
              </div>
              <template v-for="(row, index) in hidden_columns" :key="index">
                <div
                  :id="row[unique_column_key]"
                  :data-column-name="row[unique_column_key]"
                  class="box"
                >
                  <q-checkbox
                    :data-column-name="row[unique_column_key]"
                    v-model="row.selected"
                  />
                  {{ $t(row.label) }}
                </div>
              </template>
            </div>

            <!-- middle buttons -->
            <div class="rounded-borders overflow-hidden content-center">
              <div class="row justify-end items-start">
                <f-btn
                  class="q-mr-md mt-20"
                  icon="arrow_back"
                  @click="moveToHideColumnList"
                >
                  <q-tooltip>{{
                    $t('move_to_visibile_button_tooltip')
                  }}</q-tooltip>
                </f-btn>
              </div>

              <div class="row justify-end items-start">
                <f-btn
                  class="q-mr-md mt-20"
                  icon="arrow_forward"
                  @click="moveToShowColumnList"
                >
                  <q-tooltip>
                    {{ $t('move_to_hidden_button_tooltip') }}
                  </q-tooltip>
                </f-btn>
              </div>
            </div>
            <!-- Visible list -->

            <div class="drop-target rounded-borders">
              <div
                class="box row justify-center items-center"
                style="border-bottom: 1px solid grey"
              >
                {{ $t('visible_columns') }}
              </div>

              <div class="visible-columns-parent">
                <template v-for="(row, index) in visible_columns" :key="index">
                  <div draggable="true" class="draggable-box">
                    <div
                      draggable="true"
                      :id="row[unique_column_key]"
                      :data-column-name="row[unique_column_key]"
                      class="box"
                      :data-order="row.order"
                    >
                      <q-icon name="drag_indicator" size="xs" />
                      <q-checkbox
                        :data-order="row.order"
                        :data-column-name="row[unique_column_key]"
                        v-model="row.selected"
                        class="box-checkbox"
                      />
                      <q-icon
                        v-if="row.hasOwnProperty('doc_type_key')"
                        flat
                        dense
                        name="close"
                        size="24px"
                        color="red"
                        @click="removeDocTypeColumn(row[unique_column_key])"
                      >
                      </q-icon>
                      {{ $t(row.label) }}
                    </div>
                  </div>
                </template>
              </div>
            </div>
          </div>

          <div class="row justify-end items-start q-mt-md">
            <f-btn
              appearance="cancel"
              :label="$t('cancel')"
              @click="show_column_settings = false"
            />

            <f-btn
              :label="$t('done')"
              class="q-ml-sm"
              @click="saveSettings()"
            />
          </div>
        </div>
      </q-card-section>

      <q-inner-loading :showing="processing">
        <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
      </q-inner-loading>
    </q-card>
  </q-dialog>

  <!-- Document type fields selections -->
</template>

<script lang="ts">
// @ts-nocheck

import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { i18n } from 'src/boot/i18n';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import {
  getSavedColumns as getColumns,
  saveColumnOrder as saveColumns,
} from 'src/utils/columnSettingsUtil';

export default defineComponent({
  props: {
    columns_key: {
      type: String,
      required: true,
    },
    table_columns: {
      type: Array<dynamicObj>,
      required: true,
    },
    label: {
      type: String,
      default: i18n.t('table_column_settings_tooltip'),
    },
    unique_column_key: {
      type: String,
      required: false,
      default: 'name',
    },
  },
  
  mounted() {
    this.init();

    document.addEventListener('add_columns', this.addColumns);
  },
  unmounted: function () {
    document.removeEventListener('add_columns', this.addColumns);
  },
  data() {
    return {
      dragSrcEl: {} as any,
      clearInterval: 0 as any,
    };
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    this.removeDragEvents();
    next();
  },
  methods: {
    beforePopupShow() {
      this.init();
      this.show_column_settings = true;
    },
    async getSavedColumns() {
      try {
        this.visible_columns = await getColumns({
          settingKey: this.columns_key.toUpperCase(),
          tableColumns: this.table_columns,
        });
      } catch (err) {
        this.visible_columns = { ...this.table_columns };
      }
      return this.visible_columns;
    },
    init() {
      this.elements_loaded = false;
      this.visible_columns = [] as dynamicObj[];
      this.visible_columns_obj_list = {} as dynamicObj;
      this.hidden_columns = {} as any;
      this.setColumns();

      // attach events after element rendering
      this.intervalManager();
    },

    async setColumns() {
      await this.setVisibleColumns();
      this.setHiddenColumns();
    },

    setHiddenColumns() {
      for (const [key, value] of Object.entries(this.table_columns)) {
        if (this.visible_columns_obj_list.hasOwnProperty(key)) {
          continue;
        }
        const item = value;
        item.selected = false;
        item.label = this.getColumnLabel(item);
        this.hidden_columns[item[this.unique_column_key]] = item;
      }
    },

    async setVisibleColumns() {
      const visible_columns = await this.getSavedColumns();
      this.setVibileColumnsForView(visible_columns);
      this.visible_columns_obj_list = visible_columns;
    },

    setVibileColumnsForView(visible_columns: dynamicObj) {
      this.visible_columns = [] as dynamicObj[];
      for (const key in visible_columns) {
        visible_columns[key].selected = false;
        visible_columns[key].label = this.getColumnLabel(visible_columns[key]);
        this.visible_columns.push(visible_columns[key]);
      }
      this.sortVisibleColumns();
    },

    moveToHideColumnList() {
      this.visible_columns.forEach((item: any, index: number) => {
        if (
          !this.visible_columns_obj_list[item[this.unique_column_key]].selected
        ) {
          return;
        }
        const key = item[this.unique_column_key];
        this.visible_columns_obj_list[key].selected = false;
        this.hidden_columns[key] = this.visible_columns_obj_list[key];
        delete this.visible_columns_obj_list[key];
      });
      this.setVibileColumnsForView(this.visible_columns_obj_list);
    },

    moveToShowColumnList() {
      for (var key of Object.keys(this.hidden_columns)) {
        if (!this.hidden_columns[key].selected) {
          continue;
        }
        this.hidden_columns[key].selected = false;
        this.visible_columns_obj_list[key] = this.hidden_columns[key];
        delete this.hidden_columns[key];
      }
      this.setVibileColumnsForView(this.visible_columns_obj_list);
    },
    getColumnLabel(item: any) {
      item.label = item[this.unique_column_key];
      const table_column = this.table_columns[item[this.unique_column_key] as keyof typeof this.table_columns] as dynamicObj;

      if(!table_column) {
        return String(item.label);
      }
      if (item.translation_key || table_column.translation_key) {
        item.label = item.translation_key || table_column.translation_key;
      }

      if (item.hasOwnProperty('doc_type_key')) {
        item.label = displayFieldLabel.methods.getFieldLabelWithFallbacks(item);
      }

      return String(item.label);
    },
    async saveSettings() {
      this.processing = true;
      await this.saveColumns(this.visible_columns_obj_list);
      this.processing = false;
      this.show_column_settings = false;
      const event = new CustomEvent('reload_columns', {});
      document.dispatchEvent(event);
    },

    // come and check for ele for every 1000 seconds untill its loaded then turn it off
    intervalManager() {
      if (this.elements_loaded && this.clearInterval === 0) {
        return;
      }
      if (this.elements_loaded && this.clearInterval !== 0) {
        this.clearInterval = 0;
        clearInterval(this.clearInterval);
        return;
      }

      this.isElementRendered();
      if (this.elements_loaded) {
        this.addDragEvents();
      }

      if (this.elements_loaded === false) {
        this.clearInterval = setTimeout(() => {
          this.intervalManager();
        }, 1000);
      }
    },

    // ------ Column Drag Events ---------
    // make sure at least one columns remain visible
    isElementRendered() {
      let items = document.querySelectorAll('.visible-columns-parent .box');
      if (items.length > 0) {
        this.elements_loaded = true;
        return true;
      }
      return false;
    },

    removeDragEvents() {
      let items = document.querySelectorAll('.visible-columns-parent .box');
      items.forEach((item: any) => {
        // remove existing
        item.removeEventListener('dragstart', this.handleDragStart);
        item.removeEventListener('dragend', this.handleDragEnd);
        item.removeEventListener('dragover', this.handleDragOver);
        item.removeEventListener('dragenter', this.handleDragEnter);
        item.removeEventListener('dragleave', this.handleDragLeave);
        item.removeEventListener('drop', this.handleDrop);
      });
    },

    addDragEvents() {
      let items = document.querySelectorAll('.visible-columns-parent .box');
      items.forEach((item: any) => {
        // remove existing
        item.removeEventListener('dragstart', this.handleDragStart);
        item.removeEventListener('dragend', this.handleDragEnd);
        item.removeEventListener('dragover', this.handleDragOver);
        item.removeEventListener('dragenter', this.handleDragEnter);
        item.removeEventListener('dragleave', this.handleDragLeave);
        item.removeEventListener('drop', this.handleDrop);

        item.addEventListener('dragstart', this.handleDragStart);
        item.addEventListener('dragend', this.handleDragEnd);
        item.addEventListener('dragover', this.handleDragOver);
        item.addEventListener('dragenter', this.handleDragEnter);
        item.addEventListener('dragleave', this.handleDragLeave);
        item.addEventListener('drop', this.handleDrop);
      });
    },

    handleDragStart(e: any) {
      e.target.style.opacity = '0.4';
      e.dataTransfer.effectAllowed = 'move';

      const column_order = e.target.getAttribute('data-order');
      const column_name = e.target.getAttribute('data-column-name');
      e.dataTransfer.setData('column_order', column_order);
      e.dataTransfer.setData('column_name', column_name);
    },

    handleDragEnd(e: any) {
      e.target.style.opacity = '1';
      let items = document.querySelectorAll('.visible-columns-parent .box');
      items.forEach(function (item, index) {
        item.classList.remove('over');
      });
    },

    handleDragOver(e: any) {
      e.preventDefault();
      return false;
    },

    handleDragEnter(e: any) {
      e.target.classList.add('over');
    },

    handleDragLeave(e: any) {
      e.target.classList.remove('over');
    },

    handleDrop(e: any) {
      e.stopPropagation(); // stops the browser from redirecting.
      e.preventDefault();

      const toIndex = +e.target.getAttribute('data-order');
      const toIndex_column_name = e.target.getAttribute('data-column-name');

      const fromIndex = +e.dataTransfer.getData('column_order');
      const fromIndex_column_name = e.dataTransfer.getData('column_name');

      // Update mein object
      this.visible_columns_obj_list[fromIndex_column_name].order = toIndex;
      this.visible_columns_obj_list[toIndex_column_name].order = fromIndex;

      this.visible_columns.forEach((item: any) => {
        if (item.name === fromIndex_column_name) {
          item.order = toIndex;
        }

        if (item.name === toIndex_column_name) {
          item.order = fromIndex;
        }
      });
      logInfo(this.visible_columns_obj_list);
      this.sortVisibleColumns();
      this.$forceUpdate();

      return false;
    },

    // ------ Column Drag Events ---------

    sortVisibleColumns() {
      this.visible_columns.sort((a: any, b: any) => {
        return a.order - b.order;
      });
    },

    onDashboardColumnDialogHide() {
      this.removeDragEvents();
      this.show_column_settings = false;
    },

    onDocTypeFieldsDialogHide() {
      this.show_doc_type_fields = false;
    },

    addColumns(e: any) {
      if (!e) {
        return;
      }

      for (const key in e.detail.selected_fields) {
        this.visible_columns_obj_list[key] = e.detail.selected_fields[key];
      }
      this.setVibileColumnsForView(this.visible_columns_obj_list);
      this.onDocTypeFieldsDialogHide();
    },

    removeDocTypeColumn(column_name: string) {
      delete this.visible_columns_obj_list[column_name];
      this.setVibileColumnsForView(this.visible_columns_obj_list);
    },
    async saveColumns(visible_columns: dynamicObj) {
      // Save as comma-separated column names
      const columnsArray = Object.values(visible_columns);
      await saveColumns(this.columns_key.toUpperCase(), columnsArray);

      this.$emit('columnsUpdated', {
        visible_columns: this.visible_columns,
        hidden_columns: this.hidden_columns,
      });
      const event = new CustomEvent('columnsUpdated', {
        detail: {
          visible_columns: this.visible_columns,
          hidden_columns: this.hidden_columns,
        },
      });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      user_settings,
      elements_loaded: ref(false),
      visible_columns: ref([] as dynamicObj[]),
      visible_columns_obj_list: ref({} as dynamicObj),
      hidden_columns: ref({} as any),
      processing: ref(false),
      show_column_settings: ref(false),
      show_doc_type_fields: ref(false),
    };
  },
});
</script>
