<template>
  <div class="row q-mb-md">
    <div
      style="margin-top: 39px"
      class="row items-start example-container dashboard-title dark-readable"
    >
      <div
        class="example-cell cursor-pointer"
        tabindex="0"
        @click="getAllCoas"
      >
        {{ $t('all') }} ({{ total_count || 0 }})
      </div>
    </div>

    <div class="col q-ml-xl">
      <div class="row justify-start">
        <div class="dashboard-search-box q-ml-md mt-20 white-inputs">
          <CoaQuickSearch />
        </div>
        <q-space />
        <div class="q-mr-sm mt-20">
          <ColumnOrganization
            :columns_key="coa_dashboard_columns_setting"
            :table_columns="table_columns as any"
          />
        </div>
        <f-btn
          square
          class="mt-20"
          @click="refreshFilters"
        >
          <Icon icon="mdi:refresh" width="20" height="20" />
          <q-tooltip>{{ $t('refresh_list') }}</q-tooltip>
        </f-btn>
      </div>
    </div>
  </div>

  <div
    class="row mb-25 relative-position"
    style="margin-bottom: 8px"
    v-if="quickFilterMap.size > 0"
  >
    <div class="dashboard-toggler-area"></div>
    <CoaSavedFilterBadges />
  </div>
</template>

<script lang="ts">

import { defineComponent } from 'vue';
import CoaQuickSearch from './filter/coa-quick-search.vue';
import { coaDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import ColumnOrganization from 'src/pages/Invoice/components/ColumnOrganization.vue';
import CoaSavedFilterBadges from 'src/pages/CertificateOfAnalysis/components/filter/coa-saved-filter-badges.vue';
import { coa_dashboard_columns_setting } from 'src/constants';

export default defineComponent({
  components: {
    
    CoaQuickSearch,
    ColumnOrganization,
    CoaSavedFilterBadges,
  },
  methods: {
    refreshFilters() {
      this.getCoaData();
    },
    getAllCoas() {
      this.quickFilterMap.clear();
      this.resetFilter();
      this.getCoaData();
    },
  },
  setup() {
    const coa_store = coaDashboardStore();
    const {
      total_count,
      table_columns,
      params,
      quickFilterMap,
    } = storeToRefs(coa_store);
    const { getCoaData, resetFilter, resetPagination } = coa_store;
    return {
      coa_dashboard_columns_setting,
      total_count,
      table_columns,
      params,
      quickFilterMap,
      getCoaData,
      resetFilter,
      resetPagination,
    };
  },
});
</script>
