<template>
  <span class="orderByParentSpan arrow-color">
    <span
      class="up-arrow orderBy absolute"
      :class="is_order_by_selected('asc') ? 'selected' : ''"
      :data-name="column_name"
      data-direction="asc"
      @click="OrderBy"
    ></span>
    <span
      class="down-arrow orderBy absolute"
      :class="is_order_by_selected('desc') ? 'selected' : ''"
      :data-name="column_name"
      data-direction="desc"
      @click="OrderBy"
    ></span>
  </span>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { coaDashboardStore } from 'src/store/main';
import { objLen } from 'src/utils/general';

export default defineComponent({
  props: {
    column_name: {
      type: String,
      required: true,
    },
    type_name: {
      type: String,
      required: false,
      default: 'coa',
    },
  },
  watch: {
    order_by: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.init();
      },
    },
  },
  mounted: function () {
    this.init();
    document.addEventListener('reset_filters', this.resetFilters);
  },
  unmounted: function () {
    document.removeEventListener('reset_filters', this.resetFilters);
  },
  methods: {
    init() {
      if (objLen(this.order_by) === 0) {
        return;
      }
      this.order_by_field = this.order_by.field_name;
      this.order_by_direction = this.order_by.direction;
    },
    is_order_by_selected(direction: string) {
      return (
        this.order_by_field == this.column_name &&
        this.order_by_direction == direction
      );
    },
    OrderBy(ev: any) {
      if (ev.target.classList.contains('selected')) {
        return;
      }

      let direction = ev.target.dataset.direction;
      let fieldName = ev.target.dataset.name;

      if (!direction || !fieldName) {
        logError('ERROR: Orderby for field', fieldName);
        return;
      }
      ev.target.classList.add('selected');
      const orderByElList = document.querySelectorAll<HTMLElement>('.orderBy');
      if (!orderByElList.length) {
        return;
      }
      for (var i = 0; i < orderByElList.length; i++) {
        let column = orderByElList[i];
        if (
          column.dataset.name != fieldName ||
          (column.dataset.name == fieldName &&
            column.dataset.direction != direction)
        ) {
          column.classList.remove('selected');
        }
      }
      this.order_by_field = fieldName;
      this.order_by_direction = direction;

      this.order_by = {
        field_name: this.order_by_field,
        direction: this.order_by_direction,
      };
      this.params.sort_by = this.order_by_field;
      this.params.sort_order = this.order_by_direction;

      this.getData();
      this.triggerApplyFilters();
    },
    async getData() {
      try {
        this.loading = true;
        await this.getCoaData();
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },
    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
    resetFilters() {
      let elements = document.getElementsByClassName('orderBy selected');
      Array.from(elements).forEach((item: any) => {
        item.classList.remove('selected');
      });
    },
  },
  data() {
    return {
      sort_order_by: ref(''),
      order_by_field: ref(''),
      order_by_direction: ref(''),
    };
  },
  setup() {
    const coa_store = coaDashboardStore();
    const { order_by, params, loading } = storeToRefs(coa_store);
    const { getCoaData } = coa_store;

    return {
      params,
      order_by,
      loading,
      getCoaData,
    };
  },
});
</script>

